// 1. Function Declaration: Entire function is hoisted to top of scope
console.log(declaredGreet("Alice")); // Works! (Outputs: Hello, Alice)

function declaredGreet(name) {
  return `Hello, ${name}`;
}

// 2. Function Expression: Assigned to a variable; variable declaration is hoisted, but NOT the function assignment
// console.log(expressedGreet("Bob")); // ReferenceError: Cannot access before initialization!

const expressedGreet = function(name) {
  return `Greetings, ${name}`;
};

console.log(expressedGreet("Bob")); // Works here after definition

const timer = {
  seconds: 0,
  start() {
    // Standard callback function re-binds 'this' to the global/window object
    // Arrow function captures 'this' lexically from surrounding 'start' method!
    setInterval(() => {
      this.seconds++;
      console.log(`Elapsed: ${this.seconds}s`);
    }, 1000);
  }
};

// Concise arrow function expressions:
const square = x => x * x;
const add = (a, b) => a + b;

console.log(square(6)); // 36

const globalVar = "I am global";

function outerFunction() {
  const functionScopedVar = "I am inside function";

  if (true) {
    const blockScopedVar = "I am inside if-block";
    console.log(globalVar);          // Accessible
    console.log(functionScopedVar);  // Accessible
    console.log(blockScopedVar);     // Accessible
  }

  // console.log(blockScopedVar); // ReferenceError: Not accessible outside the block
}

outerFunction();
// console.log(functionScopedVar); // ReferenceError: Not accessible outside function

function createCounter(initialValue = 0) {
  // Private internal state variable
  let count = initialValue;

  // Returned object retains reference to the lexical environment of createCounter
  return {
    increment() {
      count++;
      return count;
    },
    decrement() {
      count--;
      return count;
    },
    getValue() {
      return count;
    }
  };
}

const counterA = createCounter(10);
console.log(counterA.increment()); // 11
console.log(counterA.increment()); // 12
console.log(counterA.getValue());  // 12
// 'count' cannot be directly accessed or corrupted from the outside!
